import{_ as e,c as t,o,ag as a}from"./chunks/framework.Dvzsf5EQ.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dependencies.md","filePath":"guide/dependencies.md","lastUpdated":1764669597000}'),i={name:"guide/dependencies.md"};function s(n,r,l,c,p,u){return o(),t("div",null,[...r[0]||(r[0]=[a('<h2 id="зовнішні-залежності" tabindex="-1">Зовнішні залежності <a class="header-anchor" href="#зовнішні-залежності" aria-label="Permalink to &quot;Зовнішні залежності&quot;">​</a></h2><p>У цьому розділі зібрані <strong>всі основні та другорядні пакети</strong>, які використовує AgencyOS, з коротким описом та посиланнями на офіційну документацію.</p><blockquote><p><strong>Примітка:</strong> версії вказані орієнтовно; актуальні значення дивіться у <code>package.json</code>.</p></blockquote><hr><h2 id="runtime" tabindex="-1">Runtime <a class="header-anchor" href="#runtime" aria-label="Permalink to &quot;Runtime&quot;">​</a></h2><ul><li><p><strong>Node.js</strong><br> Runtime середовище для виконання JavaScript/TypeScript.<br> Документація: <a href="https://nodejs.org" target="_blank" rel="noreferrer"><code>https://nodejs.org</code></a></p></li><li><p><strong>pnpm</strong><br> Швидкий менеджер пакетів з підтримкою монорепозиторіїв.<br> Документація: <a href="https://pnpm.io" target="_blank" rel="noreferrer"><code>https://pnpm.io</code></a></p></li></ul><hr><h2 id="core-framework" tabindex="-1">Core Framework <a class="header-anchor" href="#core-framework" aria-label="Permalink to &quot;Core Framework&quot;">​</a></h2><ul><li><p><strong>nuxt</strong><br> Nuxt 3 — фреймворк поверх Vue 3 з SSR, SSG та повним стеком для побудови веб‑додатків.<br> Документація: <a href="https://nuxt.com" target="_blank" rel="noreferrer"><code>https://nuxt.com</code></a></p></li><li><p><strong>vue 3</strong> (як частина Nuxt)<br> Реактивний фронтенд‑фреймворк.<br> Документація: <a href="https://vuejs.org" target="_blank" rel="noreferrer"><code>https://vuejs.org</code></a></p></li><li><p><strong>typescript</strong><br> Типізований супермножина JavaScript, використовується по всьому проєкту.<br> Документація: <a href="https://www.typescriptlang.org/docs" target="_blank" rel="noreferrer"><code>https://www.typescriptlang.org/docs</code></a></p></li><li><p><strong>vue-tsc</strong><br> Перевірка типів Vue SFC (CLI для TypeScript + Vue).<br> Документація: <a href="https://github.com/vuejs/language-tools" target="_blank" rel="noreferrer"><code>https://github.com/vuejs/language-tools</code></a></p></li></ul><hr><h2 id="directus-дані" tabindex="-1">Directus &amp; дані <a class="header-anchor" href="#directus-дані" aria-label="Permalink to &quot;Directus &amp; дані&quot;">​</a></h2><ul><li><p><strong>@directus/sdk</strong><br> Офіційний SDK для роботи з Directus (REST).<br> Документація: <a href="https://docs.directus.io/reference/sdk" target="_blank" rel="noreferrer"><code>https://docs.directus.io/reference/sdk</code></a></p></li><li><p><strong>vue-dompurify-html</strong><br> Vue‑обгортка над DOMPurify для безпечного рендерингу HTML з Directus.<br> Документація: <a href="https://github.com/LeSuisse/vue-dompurify-html" target="_blank" rel="noreferrer"><code>https://github.com/LeSuisse/vue-dompurify-html</code></a></p></li><li><p><strong>uuid / @types/uuid</strong><br> Генерація UUID, типи для UUID в TypeScript.<br> Документація: <a href="https://github.com/uuidjs/uuid" target="_blank" rel="noreferrer"><code>https://github.com/uuidjs/uuid</code></a></p></li></ul><hr><h2 id="nuxt‐модулі-офіціині-спільноти" tabindex="-1">Nuxt‑модулі (офіційні / спільноти) <a class="header-anchor" href="#nuxt‐модулі-офіціині-спільноти" aria-label="Permalink to &quot;Nuxt‑модулі (офіційні / спільноти)&quot;">​</a></h2><ul><li><p><strong>@nuxt/ui</strong><br> Компонентна бібліотека Nuxt UI (карти, кнопки, модальні вікна, форми тощо).<br> Документація: <a href="https://ui.nuxt.com" target="_blank" rel="noreferrer"><code>https://ui.nuxt.com</code></a></p></li><li><p><strong>@nuxt/icon</strong><br> Уніфікований модуль для підключення іконок (Iconify, SVG, кастомні).<br> Документація: <a href="https://github.com/nuxt-modules/icon" target="_blank" rel="noreferrer"><code>https://github.com/nuxt-modules/icon</code></a></p></li><li><p><strong>@nuxt/image</strong><br> Модуль оптимізації зображень (lazy‑load, формати, CDN).<br> Документація: <a href="https://image.nuxt.com" target="_blank" rel="noreferrer"><code>https://image.nuxt.com</code></a></p></li><li><p><strong>@nuxtjs/color-mode</strong><br> Управління кольоровим режимом (light/dark/system) через класи та cookies.<br> Документація: <a href="https://color-mode.nuxtjs.org" target="_blank" rel="noreferrer"><code>https://color-mode.nuxtjs.org</code></a></p></li><li><p><strong>@nuxtjs/google-fonts</strong><br> Автоматичне підключення Google Fonts з кешуванням і preload.<br> Документація: <a href="https://google-fonts.nuxtjs.org" target="_blank" rel="noreferrer"><code>https://google-fonts.nuxtjs.org</code></a></p></li><li><p><strong>@nuxtjs/seo</strong><br> Комплексний SEO‑модуль (meta, OG, sitemap, robots, schema.org, og-image).<br> Документація: <a href="https://nuxtseo.com" target="_blank" rel="noreferrer"><code>https://nuxtseo.com</code></a></p></li><li><p><strong>@vueuse/nuxt</strong><br> Nuxt‑обгортка для VueUse (auto‑import composables).<br> Документація: <a href="https://vueuse.org/guide/#nuxt" target="_blank" rel="noreferrer"><code>https://vueuse.org/guide/#nuxt</code></a></p></li></ul><hr><h2 id="ui-ux-та-анімаціі" tabindex="-1">UI / UX та анімації <a class="header-anchor" href="#ui-ux-та-анімаціі" aria-label="Permalink to &quot;UI / UX та анімації&quot;">​</a></h2><ul><li><p><strong>Tailwind CSS</strong> (через <code>@nuxtjs/tailwindcss</code>)<br> Utility‑first CSS фреймворк для стилізації інтерфейсу.<br> Документація: <a href="https://tailwindcss.com" target="_blank" rel="noreferrer"><code>https://tailwindcss.com</code></a></p></li><li><p><strong>@nuxtjs/tailwindcss</strong><br> Nuxt‑модуль для інтеграції Tailwind CSS.<br> Документація: <a href="https://tailwindcss.com/docs/guides/nuxtjs" target="_blank" rel="noreferrer"><code>https://tailwindcss.com/docs/guides/nuxtjs</code></a></p></li><li><p><strong>@tailwindcss/forms</strong><br> Офіційний Tailwind плагін для стилізації форм.<br> Документація: <a href="https://github.com/tailwindlabs/tailwindcss-forms" target="_blank" rel="noreferrer"><code>https://github.com/tailwindlabs/tailwindcss-forms</code></a></p></li><li><p><strong>@tailwindcss/typography</strong><br> Tailwind Typography (prose‑класи) для контенту/блогів.<br> Документація: <a href="https://github.com/tailwindlabs/tailwindcss-typography" target="_blank" rel="noreferrer"><code>https://github.com/tailwindlabs/tailwindcss-typography</code></a></p></li><li><p><strong>@headlessui/vue</strong><br> Headless UI компоненти (модальні, меню, списки) з підтримкою а11y.<br> Документація: <a href="https://headlessui.com" target="_blank" rel="noreferrer"><code>https://headlessui.com</code></a></p></li><li><p><strong>@formkit/auto-animate</strong><br> Простий auto‑animate для плавних переходів в списках/формах.<br> Документація: <a href="https://auto-animate.formkit.com" target="_blank" rel="noreferrer"><code>https://auto-animate.formkit.com</code></a></p></li><li><p><strong>@vueuse/core</strong><br> Набір готових Vue composables (таймери, сенсори, хелпери для браузера тощо).<br> Документація: <a href="https://vueuse.org" target="_blank" rel="noreferrer"><code>https://vueuse.org</code></a></p></li><li><p><strong>@vueuse/motion</strong><br> Анімації та motion‑примітиви на базі Motion One.<br> Документація: <a href="https://motion.vueuse.org" target="_blank" rel="noreferrer"><code>https://motion.vueuse.org</code></a></p></li><li><p><strong>v-perfect-signature</strong><br> Компонент для захоплення рукописного підпису (canvas). Використовується в пропозиціях.<br> Репозиторій: <a href="https://github.com/maxios666/v-perfect-signature" target="_blank" rel="noreferrer"><code>https://github.com/maxios666/v-perfect-signature</code></a></p></li></ul><hr><h2 id="платежі-та-stripe" tabindex="-1">Платежі та Stripe <a class="header-anchor" href="#платежі-та-stripe" aria-label="Permalink to &quot;Платежі та Stripe&quot;">​</a></h2><ul><li><p><strong>stripe</strong><br> Офіційна Node.js бібліотека Stripe (server‑side API).<br> Документація: <a href="https://stripe.com/docs/libraries/node" target="_blank" rel="noreferrer"><code>https://stripe.com/docs/libraries/node</code></a></p></li><li><p><strong>@stripe/stripe-js</strong><br> Stripe.js для клієнта (checkout, payment elements, billing portal).<br> Документація: <a href="https://stripe.com/docs/js" target="_blank" rel="noreferrer"><code>https://stripe.com/docs/js</code></a></p></li></ul><hr><h2 id="маркдаун-та-контент" tabindex="-1">Маркдаун та контент <a class="header-anchor" href="#маркдаун-та-контент" aria-label="Permalink to &quot;Маркдаун та контент&quot;">​</a></h2><ul><li><p><strong>micromark</strong><br> Низькорівневий Markdown‑парсер, використовується для обробки контенту.<br> Документація: <a href="https://github.com/micromark/micromark" target="_blank" rel="noreferrer"><code>https://github.com/micromark/micromark</code></a></p></li><li><p><strong>micromark-extension-gfm</strong><br> Розширення micromark для GitHub‑flavored Markdown (таблиці, task‑листи тощо).<br> Документація: <a href="https://github.com/micromark/micromark-extension-gfm" target="_blank" rel="noreferrer"><code>https://github.com/micromark/micromark-extension-gfm</code></a></p></li></ul><hr><h2 id="іконки" tabindex="-1">Іконки <a class="header-anchor" href="#іконки" aria-label="Permalink to &quot;Іконки&quot;">​</a></h2><ul><li><p><strong>@iconify-json/material-symbols</strong><br> JSON‑набір іконок Material Symbols для Iconify.<br> Документація: <a href="https://iconify.design" target="_blank" rel="noreferrer"><code>https://iconify.design</code></a></p></li><li><p><strong>@iconify-json/mdi</strong><br> JSON‑набір іконок Material Design Icons для Iconify.<br> Документація: <a href="https://iconify.design" target="_blank" rel="noreferrer"><code>https://iconify.design</code></a></p></li></ul><hr><h2 id="якість-коду-та-інструменти-розробки" tabindex="-1">Якість коду та інструменти розробки <a class="header-anchor" href="#якість-коду-та-інструменти-розробки" aria-label="Permalink to &quot;Якість коду та інструменти розробки&quot;">​</a></h2><ul><li><p><strong>eslint</strong><br> Лінтер для JavaScript/TypeScript/Vue.<br> Документація: <a href="https://eslint.org" target="_blank" rel="noreferrer"><code>https://eslint.org</code></a></p></li><li><p><strong>eslint-plugin-vue</strong><br> Правила ESLint для Vue 3 / SFC.<br> Документація: <a href="https://eslint.vuejs.org" target="_blank" rel="noreferrer"><code>https://eslint.vuejs.org</code></a></p></li><li><p><strong>@nuxtjs/eslint-module</strong><br> Інтеграція ESLint у Nuxt (lint під час розробки/білду).<br> Документація: <a href="https://eslint.nuxtjs.org" target="_blank" rel="noreferrer"><code>https://eslint.nuxtjs.org</code></a></p></li><li><p><strong>@nuxtjs/eslint-config-typescript</strong><br> Готовий ESLint конфіг для Nuxt + TypeScript.<br> Документація: <a href="https://github.com/nuxt/eslint-config" target="_blank" rel="noreferrer"><code>https://github.com/nuxt/eslint-config</code></a></p></li><li><p><strong>prettier</strong><br> Форматер коду (JS/TS/Vue/Markdown/YAML).<br> Документація: <a href="https://prettier.io" target="_blank" rel="noreferrer"><code>https://prettier.io</code></a></p></li><li><p><strong>eslint-config-prettier</strong><br> Вимикає конфліктні ESLint‑правила, щоб не дублювати роботу Prettier.</p></li><li><p><strong>eslint-plugin-prettier</strong><br> Запускає Prettier як ESLint‑rule.<br> Документація: <a href="https://github.com/prettier/eslint-plugin-prettier" target="_blank" rel="noreferrer"><code>https://github.com/prettier/eslint-plugin-prettier</code></a></p></li></ul><hr><h2 id="підсумок" tabindex="-1">Підсумок <a class="header-anchor" href="#підсумок" aria-label="Permalink to &quot;Підсумок&quot;">​</a></h2><p>Цей список охоплює <strong>усі основні (runtime) та другорядні (dev‑tooling) залежності</strong> з <code>package.json</code>.<br> Для деталей по конфігурації дивіться також:</p><ul><li><a href="/docs/guide/configuration.html">Конфігурація</a></li><li><a href="/docs/architecture/key-files.html">Архітектура / Ключові файли</a></li></ul>',34)])])}const h=e(i,[["render",s]]);export{d as __pageData,h as default};
